extends EstragonSurface
# Authored GDScript: literals containing markup are ordinary strings.
const DESCRIPTION: String = "<Rect> is not markup inside a string"
var spacing: float = 12.0
var header_height: float = 48.0
var sidebar_width: float = 120.0
var accent: Color = Color("8566e0")
var constructions: int = 0


func _init() -> void:
    set_root(build_view())


func make_panel(panel_width: float, color: Color) -> EstragonRect:
    constructions += 1
    return <Rect width={panel_width} fill_height={true} fill={color} />


func build_view() -> EstragonVBox:
    var small: bool = sidebar_width < 80.0
    var actual_gap: float = spacing / 2.0 if small else spacing
    return (
        <VBox gap={actual_gap}>
            <Rect height={header_height + 8.0} fill_width="true" fill={accent} />
            <HBox gap={spacing} fill_width={true} fill_height="true">
                {make_panel(sidebar_width, Color("30c9b0"))}
                <Rect fill_width="true" fill_height={true}
                    fill={Color("50466f") if sidebar_width > 0 else Color.BLACK} />
            </HBox>
        </VBox>
    )


func rebuild() -> void:
    # Explicit construction-time values, not reactive bindings.
    set_root(build_view())

extends RefCounted
const MULTILINE: String = """<Rect/> } is literal
    # <HBox> still a string
"""
const RAW: String = r"<Rect>\t\"}"
var events: Array[int] = []
var initial: EstragonRect = <Rect width="2" height="2"/>


static func _gogo_build_0() -> int:
    return 99


func mark(value: int) -> float:
    events.append(value)
    return float(value)


func make_child() -> EstragonRect:
    events.append(3)
    return <Rect width={7.0} height="5" />


func build() -> EstragonVBox:
    var left: int = 1
    var threshold: int = 2
    var comparison: bool = (left<threshold and left<=threshold and 8 >> 1 == 4)
    var values: Dictionary = {"width": 5.0, "text": "} <Rect>"}
    var callback: Callable = func() -> EstragonRect:
        return <Rect width={1.0} height="2" />
    var child: EstragonRect = callback.call()
    if not comparison:
        return <VBox/>
    return <VBox gap={mark(1)}>
        <Rect width={mark(2) + (5 / 2)} height={float(values["width"])}
            fill_width={left
                <threshold} fill={Color("abcdef")} />
        {make_child()}
        {child}
        {<Rect width={4.0} height="5" />}
    </VBox>


func loop_children() -> EstragonHBox:
    var row := <HBox gap="1"/>
    for index in range(2):
        row.add_child(<Rect width={float(index + 1)} height="2" />)
    return row


func continued_comparison() -> bool:
    var left: int = 1
    var right: int = 2
    return left \
        <right


func conditional_child(flag: bool) -> EstragonVBox:
    return <VBox>{<Rect width={mark(8)} height="2"/> if flag else <Rect width={mark(9)} height="2"/>}</VBox>


static func static_panel() -> EstragonRect:
    return <Rect width={3.0} height="1"/>

extends RefCounted

class Receiver extends EstragonRect:
    var calls: int = 0
    func receive() -> void:
        calls += 1

var events: Array[String] = []
var receiver: Receiver = Receiver.new()

func record(value: String) -> void:
    events.append(value)

func label(value: String) -> String:
    events.append(value)
    return value

func callback(value: String) -> Callable:
    events.append(value)
    return record.bind(value)

func build() -> EstragonVBox:
    var local: Callable = record.bind("local")
    return <VBox>
        <Button pressed={callback("first")} text={label("label")} />
        <Button text="Local" pressed={local} color={Color.CORAL} font_size={22} disabled={false} />
        <Button text="Lambda" pressed={func() -> void: record("lambda")} />
    </VBox>

func build_receiver_button() -> EstragonButton:
    return <Button text="Receiver" pressed={receiver.receive}/>

static func build_static(callback_value: Callable) -> EstragonButton:
    return <Button text="Static" pressed={callback_value}/>

func build_capture(payload: RefCounted) -> EstragonButton:
    return <Button text="Capture" pressed={func() -> void: payload.set_meta("called", true)}/>
